action.mutation:
mutation CreateProductionRun($payload: [ProductionRunCreatePayloadInput!]!) {
  mutation: createProductionRun(payload: $payload) { 
    id
    number
  }
}

mutation UpdateProductionRun($payload: [ProductionRunUpdatePayloadInput!]!) {
  mutation: updateProductionRun(payload: $payload) { 
    id
    number
  }
}

mutation DeleteProductionRun($payload: [ProductionRunDeletePayloadInput!]!) {
  mutation: deleteProductionRun(payload: $payload) { 
    id
    number
  }
}
